def solve_m_3():
    """
    Checks for solutions for m=3.
    Equation: 196 * b3 = 14 * b2 + 8 * b1 + 2 * b0
    Constraints: b3 in [1, 6], b2, b1, b0 in [0, 6]
    """
    solutions = []
    for b3 in range(1, 7):
        lhs = 196 * b3
        # Max RHS is 14 * 6 + 8 * 6 + 2 * 6 = 144
        if lhs > 144:
            # Since LHS increases with b3, we can stop early
            break

        for b2 in range(7):
            for b1 in range(7):
                for b0 in range(7):
                    rhs = 14 * b2 + 8 * b1 + 2 * b0
                    if lhs == rhs:
                        solutions.append((b3, b2, b1, b0))
    return solutions

def solve_m_4():
    """
    Checks for solutions for m=4.
    Equation: 1029 * b4 = 147 * b3 + 63 * b2 + 15 * b1 + 3 * b0
    Constraints: b4 in [1, 6], b3, b2, b1, b0 in [0, 6]
    """
    solutions = []
    for b4 in range(1, 7):
        lhs = 1029 * b4

        # Calculate max RHS for b4=1 (Max RHS = 147*6 + 63*6 + 15*6 + 3*6 = 882 + 378 + 90 + 18 = 1368)
        # If b4=1, LHS=1029. This is possible.
        # If b4=2, LHS=2058. This is impossible since max RHS is 1368.
        if b4 >= 2:
            break 

        # Check only b4 = 1, since LHS > Max RHS for b4 >= 2
        if b4 == 1:
            for b3 in range(7):
                for b2 in range(7):
                    for b1 in range(7):
                        for b0 in range(7):
                            rhs = 147 * b3 + 63 * b2 + 15 * b1 + 3 * b0
                            if lhs == rhs:
                                solutions.append((b4, b3, b2, b1, b0))
    return solutions

